Approach: build every tree for real and compute its checksum by walking it, using a bump-pointer arena instead of `new`/`delete`.

- **Arena allocation:** each thread owns a contiguous node buffer. A tree is built recursively with pointer bumps and walked to count its nodes. The arena is reset (offset = 0) before the next tree, so short-lived trees cost no deallocation.
- **Checksum:** a tree of depth `d` has `2^(d+1) - 1` nodes, and the walk returns exactly that count.
- **Depth parameters:**
  - `max_depth = max(6, N)`.
  - The stretch tree has depth `max_depth + 1`.
  - For each depth `d = 4, 6, ..., max_depth`, `2^(max_depth - d + 4)` trees are built.
- **Parallelism:** for each depth, the iterations are split across hardware threads. Each thread uses its own arena and accumulates a partial sum. The partial sums are added after joining, so the output order stays deterministic.
- **Long-lived tree:** it is built before the depth loop in its own arena and checked after the loop.
- **Output:** lines are printed in the required format with the exact `\t` separators.

```cpp
#include <cstdio>
#include <cstdlib>
#include <vector>
#include <thread>
#include <algorithm>

struct Node { Node* l; Node* r; };

struct Arena {
    std::vector<Node> buf;
    size_t pos = 0;
    void reserve(int depth) {
        size_t need = ((size_t)1 << (depth + 1));
        if (buf.size() < need) buf.resize(need);
    }
    void reset() { pos = 0; }
    Node* build(int d) {
        Node* n = &buf[pos++];
        if (d > 0) {
            n->l = build(d - 1);
            n->r = build(d - 1);
        } else {
            n->l = n->r = nullptr;
        }
        return n;
    }
};

static long long check(const Node* n) {
    if (!n->l) return 1;
    return 1 + check(n->l) + check(n->r);
}

int main(int argc, char** argv) {
    int n = argc > 1 ? atoi(argv[1]) : 18;
    const int min_depth = 4;
    int max_depth = std::max(min_depth + 2, n);
    int stretch = max_depth + 1;

    {
        Arena a; a.reserve(stretch);
        Node* t = a.build(stretch);
        printf("stretch tree of depth %d\t check: %lld\n", stretch, check(t));
    }

    Arena longA; longA.reserve(max_depth);
    Node* longTree = longA.build(max_depth);

    unsigned nt = std::thread::hardware_concurrency();
    if (nt == 0) nt = 4;
    std::vector<Arena> arenas(nt);

    for (int d = min_depth; d <= max_depth; d += 2) {
        long long iters = 1LL << (max_depth - d + min_depth);
        unsigned threads = (unsigned)std::min<long long>(nt, iters);
        std::vector<long long> sums(threads, 0);
        std::vector<std::thread> ths;
        for (unsigned t = 0; t < threads; t++) {
            ths.emplace_back([&, t]() {
                long long lo = iters * t / threads, hi = iters * (t + 1) / threads;
                Arena& a = arenas[t];
                a.reserve(d);
                long long s = 0;
                for (long long i = lo; i < hi; i++) {
                    a.reset();
                    Node* tr = a.build(d);
                    s += check(tr);
                }
                sums[t] = s;
            });
        }
        for (auto& th : ths) th.join();
        long long total = 0;
        for (auto v : sums) total += v;
        printf("%lld\t trees of depth %d\t check: %lld\n", iters, d, total);
    }

    printf("long lived tree of depth %d\t check: %lld\n", max_depth, check(longTree));
    return 0;
}
```

