**Approach**

1. **Read input.** Read all of stdin at once with `fread`, since the input can be large.
2. **Find the sequence.** Locate the header line starting with `>THREE` and collect the bases until the next `>` or end of input.
3. **Encode bases.** Map each base, upper or lower case, to a 2-bit code: A=0, C=1, G=2, T=3.
4. **Count 1-mers and 2-mers.** Use small arrays indexed by the code.
5. **Sort the frequencies.** Order by descending count; ties are broken by alphabetical order.
6. **Print the frequencies.** Each entry is printed as a percentage with `%s %.3f`, and each block is followed by a blank line.
7. **Count the fragments.** For each fragment of length k (all at most 18, so the key fits in 36 bits), slide a rolling key across the sequence and compare it with the fragment's encoded value. This is one O(n) pass per fragment and needs no hash table.
8. **Print the fragment counts.** Each line is `count\tfragment`.

The program does not use N from `argv[1]`, because the default N is 0 and all input comes from stdin.

```cpp
#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <vector>
#include <string>
#include <algorithm>
#include <cstdint>

static int code(char c){
    switch(c){case 'A':case 'a':return 0;case 'C':case 'c':return 1;case 'G':case 'g':return 2;case 'T':case 't':return 3;}
    return -1;
}

int main(int argc,char**argv){
    std::vector<char> buf;
    {
        size_t cap=1<<20,len=0;
        buf.resize(cap);
        size_t r;
        while((r=fread(buf.data()+len,1,cap-len,stdin))>0){
            len+=r;
            if(len==cap){cap*=2;buf.resize(cap);}
        }
        buf.resize(len);
    }
    size_t n=buf.size();
    size_t pos=0;
    // find >THREE
    while(pos<n){
        if(buf[pos]=='>' && pos+6<=n && memcmp(&buf[pos],">THREE",6)==0) break;
        // skip to next line
        while(pos<n && buf[pos]!='\n') pos++;
        pos++;
    }
    std::vector<unsigned char> seq;
    seq.reserve(n);
    if(pos<n){
        while(pos<n && buf[pos]!='\n') pos++;
        pos++;
        while(pos<n){
            char c=buf[pos];
            if(c=='>') break;
            int v=code(c);
            if(v>=0) seq.push_back((unsigned char)v);
            pos++;
        }
    }
    size_t L=seq.size();
    const char* AL="ACGT";
    // 1-mers
    {
        long long cnt[4]={0};
        for(size_t i=0;i<L;i++) cnt[seq[i]]++;
        std::vector<std::pair<long long,int>> v;
        for(int i=0;i<4;i++) v.push_back({cnt[i],i});
        std::stable_sort(v.begin(),v.end(),[](auto&a,auto&b){return a.first>b.first;});
        double tot=L?(double)L:1;
        for(auto&p:v) printf("%c %.3f\n",AL[p.second],100.0*p.first/tot);
        printf("\n");
    }
    {
        long long cnt[16]={0};
        for(size_t i=0;i+1<L;i++) cnt[seq[i]*4+seq[i+1]]++;
        std::vector<std::pair<long long,int>> v;
        for(int i=0;i<16;i++) v.push_back({cnt[i],i});
        std::stable_sort(v.begin(),v.end(),[](auto&a,auto&b){return a.first>b.first;});
        double tot=L>1?(double)(L-1):1;
        for(auto&p:v) printf("%c%c %.3f\n",AL[p.second>>2],AL[p.second&3],100.0*p.first/tot);
        printf("\n");
    }
    const char* frags[]={"GGT","GGTA","GGTATT","GGTATTTTAATT","GGTATTTTAATTTATAGT"};
    for(const char* f:frags){
        size_t k=strlen(f);
        uint64_t target=0;
        for(size_t i=0;i<k;i++) target=(target<<2)|code(f[i]);
        uint64_t mask=(k>=32)?~0ULL:((1ULL<<(2*k))-1);
        long long c=0;
        uint64_t key=0;
        for(size_t i=0;i<L;i++){
            key=((key<<2)|seq[i])&mask;
            if(i+1>=k && key==target) c++;
        }
        printf("%lld\t%s\n",c,f);
    }
    return 0;
}
```

