                e.append(d+i,n-i); break;
            }
            e.push_back(d[i++]);
        }
    }
    c.clear(); c.shrink_to_fit();
    // step5: \|[^|][^|]*\| -> -
    string g; g.reserve(e.size());
    {
        const char* d=e.data(); size_t n=e.size(), i=0;
        while(i<n){
            if(d[i]=='|' && i+1<n && d[i+1]!='|'){
                const char* q=(const char*)memchr(d+i+2>d+n?d+n:d+i+2,'|', i+2<=n? n-i-2:0);
                if(q){ g.push_back('-'); i=(q-d)+1; continue; }
                g.append(d+i,n-i); break;
            }
            g.push_back(d[i++]);
        }
    }
    return g.size();
