int main(int argc,char**argv){
    (void)argc;(void)argv;
    string in;
    {
        size_t cap=1<<24; in.resize(cap); size_t len=0;
        while(true){
            if(len==cap){cap*=2; in.resize(cap);}
            size_t r=fread(&in[len],1,cap-len,stdin);
            if(r==0)break;
            len+=r;
        }
        in.resize(len);
    }
    size_t origLen=in.size();
    string s; s.reserve(origLen);
    {
        const char* d=in.data(); size_t n=in.size(), i=0;
        while(i<n){
            const char* nl=(const char*)memchr(d+i,'\n',n-i);
            size_t end = nl? (size_t)(nl-d) : n;
            // segment d[i..end)
            const char* gt=(const char*)memchr(d+i,'>',end-i);
            if(gt){
                s.append(d+i,gt-(d+i));
                if(nl){ i=end+1; continue; }
                s.append(gt,(d+end)-gt);
                i=end; continue;
            }
            s.append(d+i,end-i);
            i= nl? end+1 : end;
        }
    }
    in.clear(); in.shrink_to_fit();

    long long counts[9];
    size_t finalLen=0;
    vector<thread> th;
    th.emplace_back([&]{ finalLen=substitute(s); });
    for(int k=0;k<9;k++) th.emplace_back([&,k]{ counts[k]=countPat(PATS[k],s); });
    for(auto&t:th) t.join();

    string out;
    char buf[128];
    for(int k=0;k<9;k++){ snprintf(buf,sizeof buf,"%s %lld\n",PATS[k],counts[k]); out+=buf; }
    snprintf(buf,sizeof buf,"\n%zu\n%zu\n%zu\n",origLen,s.size(),finalLen); out+=buf;
    fwrite(out.data(),1,out.size(),stdout);
    return 0;
}
