## Approach

1. Read all of stdin into one buffer.
2. Handle each FASTA record in turn:
   - Copy the header line (starting with `>`) to the output unchanged.
   - Collect the sequence bases into a contiguous buffer, skipping newlines and `\r`.
3. Reverse the sequence and complement each base with a 256-entry lookup table:
   - Lowercase IUPAC codes map to the uppercase complement, matching the reference benchmark.
   - Any unknown character passes through unchanged.
4. Re-wrap the output at the record's original line width. This is the length of its first sequence line, with 60 as the fallback.
5. Write everything in a single `fwrite`.
6. `N` is read from `argv[1]` but not used.

## Program

```cpp
#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <vector>
#include <string>
#include <unistd.h>

int main(int argc, char** argv) {
    int N = argc > 1 ? atoi(argv[1]) : 0; (void)N;

    // read all stdin
    std::vector<char> in;
    {
        size_t cap = 1 << 24, len = 0;
        in.resize(cap);
        while (true) {
            if (len == cap) { cap *= 2; in.resize(cap); }
            ssize_t r = read(0, in.data() + len, cap - len);
            if (r <= 0) break;
            len += r;
        }
        in.resize(len);
    }

    unsigned char tbl[256];
    for (int i = 0; i < 256; i++) tbl[i] = (unsigned char)i;
    const char* from = "ACBDGHKMNSRUTWVYacbdghkmnsrutwvy";
    const char* to   = "TGVHCDMKNSYAAWBRTGVHCDMKNSYAAWBR";
    for (int i = 0; from[i]; i++) tbl[(unsigned char)from[i]] = (unsigned char)to[i];

    const char* p = in.data();
    const char* end = p + in.size();
    std::vector<char> out;
    out.reserve(in.size() + 1024);
    std::vector<char> seq;

    while (p < end) {
        if (*p != '>') {
            // skip stray content until a header
            const char* nl = (const char*)memchr(p, '\n', end - p);
            p = nl ? nl + 1 : end;
            continue;
        }
        const char* nl = (const char*)memchr(p, '\n', end - p);
        const char* hend = nl ? nl : end;
        out.insert(out.end(), p, hend);
        out.push_back('\n');
        p = nl ? nl + 1 : end;

        seq.clear();
        size_t width = 0;
        while (p < end && *p != '>') {
            const char* l = (const char*)memchr(p, '\n', end - p);
            const char* le = l ? l : end;
            const char* lr = le;
            if (lr > p && lr[-1] == '\r') lr--;
            if (width == 0 && lr > p) width = lr - p;
            seq.insert(seq.end(), p, lr);
            p = l ? l + 1 : end;
        }
        if (width == 0) width = 60;

        size_t n = seq.size();
        size_t base = out.size();
        size_t lines = (n + width - 1) / width;
        out.resize(base + n + lines);
        char* o = out.data() + base;
        const unsigned char* s = (const unsigned char*)seq.data();
        size_t idx = n;
        while (idx > 0) {
            size_t k = idx < width ? idx : width;
            for (size_t j = 0; j < k; j++) o[j] = (char)tbl[s[idx - 1 - j]];
            o += k;
            *o++ = '\n';
            idx -= k;
        }
    }

    fwrite(out.data(), 1, out.size(), stdout);
    return 0;
}
```

